# Initially generated by GitHub Copilot.
"""
Generate thumbnails from slide images under misc/what-is-mam/img/.

For every file matching misc/what-is-mam/img/slide-<slug>.png, produce a
corresponding misc/what-is-mam/img/thumb-<slug>.png scaled to THUMB_SIZE using
Lanczos resampling. New slide/thumb pairs are picked up automatically
— just drop a new slide-<slug>.png in misc/what-is-mam/img/ and re-run.
"""

import argparse
import pathlib

from PIL import Image

IMAGES_DIR = pathlib.Path("misc/what-is-mam/img")
THUMB_SIZE = (480, 270)  # 16:9 thumbnail


def make_thumb(slide_path: pathlib.Path, thumb_size: tuple[int, int]) -> None:
    thumb_path = slide_path.parent / slide_path.name.replace("slide-", "thumb-")
    img = Image.open(slide_path)
    img_thumb = img.copy()
    img_thumb.thumbnail(thumb_size, Image.LANCZOS)
    img_thumb.save(thumb_path, optimize=True)
    print(f"{slide_path.name} {img.size} -> {thumb_path.name} {img_thumb.size}")


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Generate thumbnails from slide-*.png images."
    )
    parser.add_argument(
        "--images-dir",
        type=pathlib.Path,
        default=IMAGES_DIR,
        help=f"Directory containing slide-*.png files (default: {IMAGES_DIR})",
    )
    parser.add_argument(
        "--thumb-width",
        type=int,
        default=THUMB_SIZE[0],
        help=f"Thumbnail width in pixels (default: {THUMB_SIZE[0]})",
    )
    parser.add_argument(
        "--thumb-height",
        type=int,
        default=THUMB_SIZE[1],
        help=f"Thumbnail height in pixels (default: {THUMB_SIZE[1]})",
    )
    args = parser.parse_args()
    thumb_size = (args.thumb_width, args.thumb_height)
    slides = sorted(args.images_dir.glob("slide-*.png"))
    if not slides:
        print(f"No slide-*.png files found in {args.images_dir}")
        return
    for slide_path in slides:
        make_thumb(slide_path, thumb_size)


if __name__ == "__main__":
    main()
